import React, { useState } from 'react';
import axios from 'axios';

const StepForm = () => {
  const [stepType, setStepType] = useState('');
  const [stepData, setStepData] = useState({
    chargeInfo: '',
    dischargeInfo: '',
    tripInfo: ''
  });

  const handleStepTypeChange = (e) => {
    setStepType(e.target.value);
  };

  const handleChange = (e) => {
    setStepData({
      ...stepData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const dataToSubmit = {
      stepType,
      ...stepData
    };
    axios.post('http://localhost:5000/add_vehicle', dataToSubmit)
      .then(response => {
        console.log(response.data);
      });
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Step Type:
        <select value={stepType} onChange={handleStepTypeChange}>
          <option value="">Select Step Type</option>
          <option value="charge">Charge</option>
          <option value="discharge">Discharge</option>
          <option value="trip">Trip</option>
        </select>
      </label>

      {stepType === 'charge' && (
        <div>
          <label>
            Station:
            <input
              type="text"
              name="station"
              value={stepData.station}
              onChange={handleChange}
            />
          </label>
          <label>
            Start charge:
            <input
              type="number"
              name="start_charge"
              value={stepData.start_charge}
              onChange={handleChange}
            />
          </label>
          <label>
            End charge:
            <input
              type="number"
              name="end_charge"
              value={stepData.end_charge}
              onChange={handleChange}
            />
          </label>
          <label>
            Desired charge:
            <input
              type="number"
              name="desired_charge"
              value={stepData.desired_charge}
              onChange={handleChange}
            />
          </label>
        </div>
      )}

      {stepType === 'discharge' && (
        <div>
          <label>
            Discharge Info:
            <input
              type="text"
              name="dischargeInfo"
              value={stepData.dischargeInfo}
              onChange={handleChange}
            />
          </label>
        </div>
      )}

      {stepType === 'trip' && (
        <div>
          <label>
            Trip Info:
            <input
              type="text"
              name="tripInfo"
              value={stepData.tripInfo}
              onChange={handleChange}
            />
          </label>
        </div>
      )}

      <button type="submit">Add Step</button>
    </form>
  );
};

export default StepForm;
